{
  "name": "suvadu-opencode-hook",
  "version": "0.1.1",
  "description": "OpenCode plugin that logs bash tool executions to Suvadu for AI command history and reporting.",
  "main": "suvadu-shell-hook.js",
  "exports": {
    ".": "./suvadu-shell-hook.js"
  },
  "files": [
    "suvadu-shell-hook.js",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "check:syntax": "node --check ./suvadu-shell-hook.js"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "suvadu",
    "shell-history",
    "ai-agent",
    "bash"
  ],
  "author": "Michael Bøcker-Larsen <mbl@code.boutique>",
  "license": "MIT",
  "type": "module",
  "devDependencies": {
    "@opencode-ai/plugin": "^1.2.27"
  }
}
